  select exists (
    select 1 from public.friendships f
    where (f.requester_id = p_user_id or f.addressee_id = p_user_id)
      and f.status = 'accepted'
      and (f.requester_id <> p_user_id or f.addressee_id <> p_user_id)
  )
$$;

