  on public.files for delete
  to authenticated
  using (owner_id = auth.uid() or private.is_org_admin());

create function private.enforce_file_guard()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if coalesce(current_setting('request.jwt.claims', true), '') ~* 'legal_hold' then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if new.legal_hold is distinct from old.legal_hold then
      raise exception 'legal_hold cannot be changed through the app' using errcode = '42501';
    end if;
    if new.id is distinct from old.id then
      raise exception 'file id cannot be changed' using errcode = '42501';
    end if;
  end if;
  return new;
end
$$;

create trigger enforce_file_guard
before update on public.files
for each row execute function private.enforce_file_guard();
