create function public.is_org_admin(target_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = target_org_id
      and m.user_id = auth.uid()
      and m.role = 'admin'
  );
$$;

create function public.is_sso_session()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select auth.jwt() -> 'amr' ?| array['sso/saml'];
$$;

create function public.enforce_org_session_requirement()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if current_user = 'service_role' then
    return new;
  end if;

  if not exists (
    select 1
    from public.orgs o
    where o.id = new.org_id
  ) then
    raise exception 'unknown organization';
  end if;

  if new.org_id is distinct from old.org_id then
    raise exception 'org_id cannot be changed';
  end if;

  if not exists (
    select 1
    from public.org_members m
    where m.org_id = new.org_id
      and m.user_id = auth.uid()
      and m.role = 'admin'
  ) then
    raise exception 'not allowed';
  end if;

  if new.org_id in (
    select o.id
    from public.orgs o
    where o.require_sso
  ) then
    if not public.is_sso_session() then
      raise exception 'SSO session required';
    end if;
  end if;

  return new;
end;
$$;

create trigger enforce_org_session_requirement
before insert/update on public.orgs
for each row execute function public.enforce_org_session_requirement();

