  on public.bids
  for select
  to authenticated
  using (
    bidder_id = auth.uid()
    or exists (
      select 1
      from public.auctions a
      where a.id = bids.auction_id
        and a.seller_id = auth.uid()
    )
  );

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_highest numeric;
  v_seller uuid;
begin
  if v_user is null then
    raise exception 'Not authenticated';
  end if;

  if not exists (
    select 1
    from public.auctions
    where id = p_auction_id
  ) then
    raise exception 'Unknown auction';
  end if;

  select
    highest_bid,
    seller_id
  into v_highest, v_seller
  from public.auctions
  where id = p_auction_id
  for update;

  if v_seller = v_user then
    raise exception 'Cannot bid on your own auction';
  end if;

  if now() > (select ends_at from public.auctions where id = p_auction_id) then
    raise exception 'Auction has ended';
  end if;

  if p_amount < (select starting_price from public.auctions where id = p_auction_id) then
    raise exception 'Bid is below starting price';
  end if;

  if v_highest is null and p_amount < (select starting_price from public.auctions where id = p_auction_id) then
    raise exception 'Bid is below starting price';
  end if;

  if v_highest is not null and p_amount < v_highest + (select min_increment from public.auctions where id = p_auction_id) then
    raise exception 'Bid is below the minimum increment';
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_user, p_amount);

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_user
  where id = p_auction_id;

  return p_amount;
end;
$$;
