create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_highest numeric;
  v_seller uuid;
begin
  if v_user is null then
    raise exception 'Not authenticated';
  end if;

  if not exists (
    select 1
    from public.auctions
    where id = p_auction_id
  ) then
    raise exception 'Unknown auction';
  end if;

  select
    highest_bid,
    seller_id
  into v_highest, v_seller
  from public.auctions
  where id = p_auction_id
  for update;

  if v_seller = v_user then
    raise exception 'Cannot bid on your own auction';
  end if;

