            from public.class_spots s
            where s.class_id = c.id and s.status = 'enrolled'
          ) < c.capacity)
          or (status = 'waitlisted' and (
            select count(*)::bigint
            from public.class_spots s
            where s.class_id = c.id and s.status = 'enrolled'
          ) >= c.capacity)
        )
    )
  );

